// Selection Sort implementation
function selectionSort(arr) {
  const n = arr.length;

  for (let i = 0; i < n - 1; i++) {
    let min_index = i;

    for (let j = i + 1; j < n; j++) {
      if (arr[j] < arr[min_index]) {
        min_index = j;
      }
    }

    if (min_index !== i) {
      [arr[i], arr[min_index]] = [arr[min_index], arr[i]];
    }
  }

  return arr;
}

// Example usage
const arr = [64, 25, 12, 22, 11, 22, 11];
console.log('Original:', arr);
selectionSort(arr);
console.log('Sorted:', arr); 
// [11, 11, 12, 22, 25, 64]
